 for i in range(L):
  for j in range(L-i):C[i+j]+=A[i]@B[j]
 return C%p
def inv(A):
 B=(I-A)%p;C=I.copy();D=I.copy()
 for k in range(1,L):D=mul(D,B);C=(C+D)%p
 return C
